//! Real carrier-fixture transport checks.
//!
//! The fixtures are generated by `platform/macos/salsa-hal/tools/make_fixtures.sh`
//! and are intentionally not stored in Git. Point `SALSA_TEST_SPDIF_FIXTURES`
//! at the fixture directory to run them explicitly. The tests are skipped when
//! the fixtures are absent so a default workspace test stays hermetic.

use std::path::{Path, PathBuf};

use iec61937::{AccessUnit, Codec, Depacketizer};

fn fixtures_dir() -> Option<PathBuf> {
    if let Some(path) = std::env::var_os("SALSA_TEST_SPDIF_FIXTURES") {
        let path = PathBuf::from(path);
        return path.is_dir().then_some(path);
    }
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().nth(4)?;
    let path = root.join("platform/macos/salsa-hal/fixtures");
    path.is_dir().then_some(path)
}

fn read_if_present(dir: &Path, name: &str) -> Option<Vec<u8>> {
    let path = dir.join(name);
    if !path.is_file() {
        eprintln!("skipping: {} is absent", path.display());
        return None;
    }
    Some(std::fs::read(path).expect("read fixture"))
}

fn depacketize(carrier: &[u8]) -> (Vec<AccessUnit>, Depacketizer) {
    let mut depacketizer = Depacketizer::new(48_000);
    let mut units = Vec::new();
    for chunk in carrier.chunks(8191) {
        units.extend(depacketizer.push(chunk));
    }
    (units, depacketizer)
}

#[test]
fn eac3_carrier_recovers_the_ec3_fixture() {
    let Some(dir) = fixtures_dir() else {
        eprintln!("skipping: no SPDIF fixture directory");
        return;
    };
    let Some(carrier) = read_if_present(&dir, "eac3_20s.spdif") else {
        return;
    };
    let Some(reference) = read_if_present(&dir, "eac3_20s.ec3") else {
        return;
    };

    let (units, depacketizer) = depacketize(&carrier);
    let stats = depacketizer.carrier_stats();
    assert_eq!(stats.bursts, 625);
    assert_eq!(stats.malformed_bursts, 0);
    assert_eq!(stats.unsupported_bursts, 0);
    assert_eq!(stats.null_bursts, 0);
    assert_eq!(stats.resynced_bytes, 0);

    let recovered: Vec<u8> = units
        .iter()
        .flat_map(|unit| unit.bytes())
        .copied()
        .collect();
    assert_eq!(recovered, reference);
    assert!(units.iter().all(|unit| matches!(unit, AccessUnit::Eac3(_))));
    assert_eq!(depacketizer.eac3_stats().frames, 625);
    assert_eq!(depacketizer.codec(), Some(Codec::Eac3));

    let offsets: Vec<u64> = units.iter().map(AccessUnit::carrier_offset).collect();
    assert!(offsets.windows(2).all(|pair| pair[0] < pair[1]));
}

#[test]
fn truehd_carrier_recovers_the_mlp_fixture_and_relative_timing() {
    let Some(dir) = fixtures_dir() else {
        eprintln!("skipping: no SPDIF fixture directory");
        return;
    };
    let Some(carrier) = read_if_present(&dir, "truehd_20s.spdif") else {
        return;
    };
    let Some(reference) = read_if_present(&dir, "truehd_20s.mlp") else {
        return;
    };

    let (units, depacketizer) = depacketize(&carrier);
    let stats = depacketizer.carrier_stats();
    assert_eq!(stats.bursts, 999);
    assert_eq!(stats.malformed_bursts, 0);
    assert_eq!(stats.resynced_bytes, 0);
    assert_eq!(depacketizer.truehd_stats().mat_frames, 999);
    assert_eq!(depacketizer.truehd_stats().malformed_mat_frames, 0);

    // The 20 s SPDIF fixture is truncated at a MAT-frame boundary; it carries
    // the first 23,976 access units of the 24,000-AU MLP fixture.
    assert_eq!(units.len(), 23_976);
    let recovered: Vec<u8> = units
        .iter()
        .flat_map(|unit| unit.bytes())
        .copied()
        .collect();
    assert!(recovered.len() < reference.len());
    assert_eq!(recovered, reference[..recovered.len()]);

    let mut expected = 0u64;
    let mut previous_timing = None;
    for (index, unit) in units.iter().enumerate() {
        let AccessUnit::TrueHd(unit) = unit else {
            panic!("expected a TrueHD access unit at {index}");
        };
        if let Some(previous) = previous_timing {
            expected += u64::from(unit.input_timing.wrapping_sub(previous));
        }
        assert_eq!(unit.sample_offset, expected, "access unit {index}");
        previous_timing = Some(unit.input_timing);
    }

    let offsets: Vec<u64> = units.iter().map(AccessUnit::carrier_offset).collect();
    assert!(offsets.windows(2).all(|pair| pair[0] < pair[1]));
}

#[test]
fn reset_starts_a_new_generation_for_both_codecs() {
    let Some(dir) = fixtures_dir() else {
        eprintln!("skipping: no SPDIF fixture directory");
        return;
    };
    let Some(carrier) = read_if_present(&dir, "eac3_20s.spdif") else {
        return;
    };

    let mut depacketizer = Depacketizer::new(48_000);
    let first = depacketizer.push(&carrier[..carrier.len() / 2]);
    assert!(!first.is_empty());
    assert_eq!(depacketizer.generation(), 0);
    assert!(depacketizer.eac3_stats().frames > 0);

    let frames_before = depacketizer.eac3_stats().frames;
    depacketizer.reset();
    assert_eq!(depacketizer.generation(), 1);
    assert_eq!(depacketizer.eac3_stats().frames, frames_before);

    let second = depacketizer.push(&carrier);
    assert!(!second.is_empty());
    assert!(second.iter().all(|unit| unit.generation() == 1));
}
